<template><view class="seckill pressable" @click="$emit('navigate', section)"><view><view class="seckill__heading"><text class="seckill__title">{{ section.title }}</text><text v-if="section.config?.tag" class="seckill__tag">{{ section.config.tag }}</text></view><text class="seckill__copy">{{ section.subtitle }}</text></view><view v-if="remaining" class="seckill__timer"><text>{{ remaining.hours }}</text><text class="colon">:</text><text>{{ remaining.minutes }}</text><text class="colon">:</text><text>{{ remaining.seconds }}</text></view></view></template>
<script setup>import { computed, onBeforeUnmount, onMounted, ref } from 'vue'; const props = defineProps({ section: { type: Object, required: true } }); defineEmits(['navigate']); const now = ref(Date.now()); let timer; const remaining = computed(() => { const endsAt = props.section.config?.endsAt; if (!endsAt) return null; const value = new Date(endsAt).getTime() - now.value; if (value <= 0) return null; const pad = (number) => String(number).padStart(2, '0'); return { hours: pad(Math.floor(value / 3600000)), minutes: pad(Math.floor(value % 3600000 / 60000)), seconds: pad(Math.floor(value % 60000 / 1000)) } }); onMounted(() => { timer = setInterval(() => { now.value = Date.now() }, 1000) }); onBeforeUnmount(() => clearInterval(timer))</script>
<style scoped lang="scss">.seckill{display:flex;align-items:center;justify-content:space-between;margin:20rpx 22rpx;padding:26rpx 28rpx;border-radius:8rpx;background:#182f2b;color:#fff}.seckill__heading{display:flex;align-items:center;gap:12rpx}.seckill__title{color:#ead2a8;font-size:33rpx;font-weight:700}.seckill__tag{padding:5rpx 10rpx;background:#e43a35;font-size:19rpx}.seckill__copy{display:block;margin-top:8rpx;color:#aebdb8;font-size:22rpx}.seckill__timer{display:flex;align-items:center;gap:6rpx}.seckill__timer>text:not(.colon){padding:10rpx;background:#f4ecdd;color:#2e3a36;font-size:25rpx;font-weight:700}.colon{color:#c99a55}</style>
